// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;

import org.junit.jupiter.api.Test;

/**
 * Unit spec for the cost of a factorized aggregation ({@link LmdbNativeStrategyProposal#factorizedCost}).
 * <p>
 * A factorized plan runs a nested-loop <em>prefix</em> chain and then, for every row the prefix emits, evaluates each
 * <em>tail branch</em> once. Its cost therefore has two independent properties, and both are asserted here because
 * getting either one wrong silently mis-ranks the strategy against parallel aggregation at
 * {@code LmdbNativeGroupStep.evaluateParallelOrFactorized}:
 * <ul>
 * <li>each tail branch is paid <em>once per prefix row</em>, so the branch term scales with the prefix cardinality;
 * <li>tail branches are <em>summed</em> with one another rather than multiplied, which is the entire reason
 * factorization beats the equivalent nested-loop join.
 * </ul>
 * These are stated as relationships between costs rather than as absolute numbers so that the spec stays valid when the
 * underlying cardinality estimator improves.
 */
public class LmdbNativeFactorizedCostTest {

	private static final int ROOT = 0;
	private static final int FIRST = 1;
	private static final int SECOND = 2;

	private static PatternPlan pattern(Term subject, long predicate, Term object, double estimate) {
		return new PatternPlan(subject, Term.constant(predicate), object, Term.unbound(),
				ContextConstraint.UNRESTRICTED, false, estimate);
	}

	/** A driving pattern that emits {@code rows} bindings for slot {@link #ROOT}. */
	private static PatternPlan prefixPattern(double rows) {
		return pattern(Term.slot(ROOT), 7L, Term.constant(8L), rows);
	}

	/** A tail branch correlated with the prefix through slot {@link #ROOT}. */
	private static PatternPlan branchPattern(int objectSlot, long predicate, double rows) {
		return pattern(Term.slot(ROOT), predicate, Term.slot(objectSlot), rows);
	}

	private static double cost(SlotPlan[] order, int prefixLength) {
		return LmdbNativeStrategyProposal.factorizedCost(order, prefixLength, 0L, null);
	}

	@Test
	public void tailBranchIsPaidOncePerPrefixRow() {
		PatternPlan prefix = prefixPattern(10D);
		PatternPlan branch = branchPattern(FIRST, 9L, 100D);

		double prefixRows = prefix.estimateForBoundMask(0L, null);
		double branchRowsPerProbe = branch.estimateForBoundMask(prefix.producedMask(), null);
		assertThat(prefixRows).as("fixture precondition: the prefix emits more than one row").isGreaterThan(1D);
		assertThat(branchRowsPerProbe).as("fixture precondition: the branch yields rows").isGreaterThan(0D);

		double cost = cost(new SlotPlan[] { prefix, branch }, 1);

		assertThat(cost)
				.as("the tail branch is evaluated once per prefix row, so its rows must be multiplied by the "
						+ "prefix cardinality rather than added once")
				.isGreaterThanOrEqualTo(prefixRows * branchRowsPerProbe);
	}

	@Test
	public void marginalTailBranchCostScalesWithPrefixRows() {
		double smallPrefixRows = 10D;
		double largePrefixRows = 1_000D;

		PatternPlan smallPrefix = prefixPattern(smallPrefixRows);
		PatternPlan largePrefix = prefixPattern(largePrefixRows);

		double smallMarginal = cost(new SlotPlan[] { smallPrefix, branchPattern(FIRST, 9L, 100D),
				branchPattern(SECOND, 11L, 100D) }, 1)
				- cost(new SlotPlan[] { smallPrefix, branchPattern(FIRST, 9L, 100D) }, 1);
		double largeMarginal = cost(new SlotPlan[] { largePrefix, branchPattern(FIRST, 9L, 100D),
				branchPattern(SECOND, 11L, 100D) }, 1)
				- cost(new SlotPlan[] { largePrefix, branchPattern(FIRST, 9L, 100D) }, 1);

		assertThat(smallMarginal).as("adding a branch must cost something").isGreaterThan(0D);
		assertThat(largeMarginal)
				.as("the same extra branch over a 100x larger prefix must cost proportionally more, because the "
						+ "branch is re-evaluated for every prefix row")
				.isGreaterThan(smallMarginal * 50D);
	}

	@Test
	public void tailBranchesAreSummedNotMultiplied() {
		double prefixRows = 100D;
		PatternPlan prefix = prefixPattern(prefixRows);
		PatternPlan first = branchPattern(FIRST, 9L, 100D);
		PatternPlan second = branchPattern(SECOND, 11L, 100D);

		double firstRows = first.estimateForBoundMask(prefix.producedMask(), null);
		double secondRows = second.estimateForBoundMask(prefix.producedMask(), null);

		double cost = cost(new SlotPlan[] { prefix, first, second }, 1);

		assertThat(cost)
				.as("both branches are evaluated per prefix row")
				.isGreaterThanOrEqualTo(prefixRows * (firstRows + secondRows));
		assertThat(cost)
				.as("factorization scans the branches side by side; it must never be priced as the nested-loop "
						+ "product of the branches, which is the cost it exists to avoid")
				.isLessThan(prefixRows * firstRows * secondRows);
	}

	@Test
	public void prefixOnlyPlanCostsTheChainAlone() {
		PatternPlan prefix = prefixPattern(10D);
		PatternPlan second = branchPattern(FIRST, 9L, 5D);

		double chained = cost(new SlotPlan[] { prefix, second }, 2);

		assertThat(chained)
				.as("with no tail branches the cost is exactly the nested-loop chain work")
				.isEqualTo(
						LmdbNativeOrderPlanner.cumulativePatternWork(new SlotPlan[] { prefix, second }, 2, 0L, null));
	}

	@Test
	public void unpriceableBranchRefusesToProduceACost() {
		PatternPlan prefix = prefixPattern(10D);
		// SingletonPlan does not override SlotPlan.estimate, so the estimator reports it as unknown.
		SlotPlan unpriceable = SlotPlan.singleton();

		double cost = cost(new SlotPlan[] { prefix, unpriceable }, 1);

		assertThat(cost)
				.as("a branch the estimator cannot price must make the whole proposal unpriceable rather than "
						+ "contribute zero and make factorization look cheapest")
				.isEqualTo(Double.POSITIVE_INFINITY);
	}

	@Test
	public void unpriceablePrefixChildRefusesToProduceACost() {
		SlotPlan unpriceable = SlotPlan.singleton();
		PatternPlan branch = branchPattern(FIRST, 9L, 100D);

		double cost = cost(new SlotPlan[] { unpriceable, branch }, 1);

		assertThat(cost)
				.as("an unpriceable prefix child leaves the probe count unknown, so no branch term can be trusted")
				.isEqualTo(Double.POSITIVE_INFINITY);
	}
}
